answer.sql:
SELECT 100.0 * SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) / COUNT(*) AS inpatient_percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

